-- Precomputed analytics rollups.
--
-- Hand-written rather than autogenerated: `prisma migrate dev` wants to
-- also DROP the jobs.search_vector index and its generated-column
-- expression (Prisma models that column as `Unsupported`, so it can't
-- see the GENERATED ALWAYS clause). Those statements are destructive and
-- unrelated to this change, so only the CREATE TABLE is kept.
CREATE TABLE "analytics_snapshots" (
    "key" TEXT NOT NULL,
    "payload" JSONB NOT NULL,
    "compute_ms" INTEGER NOT NULL,
    "rows_scanned" INTEGER,
    "computed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "analytics_snapshots_pkey" PRIMARY KEY ("key")
);
